/**
 * Generates a short CRM summary of the conversation for the call centre.
 * Always generated — covers mood, urgency, what matters to the customer, key context.
 */
export async function generateInquirySummary(
  history: ConversationMessage[],
  known: KnownFields
): Promise<string> {
  if (history.length === 0) return "No conversation recorded.";

  const contextLines: string[] = [];
  if (known.name)         contextLines.push(`Name: ${known.name}`);
  if (known.make)         contextLines.push(`Car: ${[known.make, known.model, known.year].filter(Boolean).join(" ")}`);
  if (known.mileage)      contextLines.push(`Mileage: ${known.mileage} km`);
  if (known.specs)        contextLines.push(`Specs: ${known.specs}`);
  if (known.loan)         contextLines.push(`Loan/mortgage: ${known.loan}`);
  if (known.sell_timeline) contextLines.push(`Sell intent: ${known.sell_timeline}`);
  if ((known as any).owner_status) contextLines.push(`Ownership: ${(known as any).owner_status}`);
  if ((known as any).car_conditions) contextLines.push(`Conditions noted: ${(known as any).car_conditions}`);

  const contextBlock = contextLines.length ? `\nKnown details:\n${contextLines.join("\n")}` : "";

  const transcript = history
    .map(m => `${m.role === "user" ? "Customer" : "Kaya"}: ${m.content}`)
    .join("\n");

  try {
    const response = await anthropic.messages.create({
      model: EXTRACTOR_MODEL,
      max_tokens: 500,
      ...NO_THINKING,
      system: `You write short CRM notes for a car-buying call centre team in Dubai.
Analyse the WhatsApp conversation and write a 3–5 sentence summary covering:
1. What the customer is looking to do (sell type, urgency, timeframe)
2. Their mood and communication style (relaxed, impatient, hesitant, price-focused, etc.)
3. Any special circumstances (loan on car, accident history, modifications, POA situation, missing docs, etc.)
4. What the call centre should know or anticipate when contacting them
5. If the customer has more than one car: list EVERY car with all details given (make, model, year, mileage, specs, loan)
Be direct and factual. No fluff. Write in third person ("The customer...").${contextBlock}`,
      messages: [{ role: "user", content: `Conversation transcript:\n${transcript}` }],
    });
    const block = response.content.find(b => b.type === "text");
    return block?.type === "text" ? block.text.trim() : "Summary unavailable.";
  } catch (e) {
    console.error("[generateInquirySummary] error:", e);
    return "Summary unavailable.";
  }
}

// ─── Hard output filter ──────────────────────────────────────────────────────
// Last line of defence: a reply containing a price, or leaking instructions, is never sent.
export const SAFE_PRICE_REPLY = "I'm not able to share a price here — you'll get the final price after the free 10–15 minute inspection at our branch.";
const SAFE_LEAK_REPLY  = "I'm here to help you sell your car. What car are you looking to sell, or is there anything else I can help with?";

export function containsPrice(text: string): boolean {
  const t = text
    .replace(/\b\d[\d,.]*\s*k?\s*(km|kms|kilomet\w*|miles?)\b/gi, " ")                    // mileage is fine
    .replace(/(\+?971|00971|\b0)\s*5\d[\s-]?\d{3}[\s-]?\d{4}\b|\b9715\d{8}\b/g, " ")       // UAE phone numbers are fine
    .replace(/(\+|\b00)\d{1,3}[\s-]?\(?\d{1,4}\)?([\s-]?\d{2,5}){2,4}\b/g, " ")               // international numbers too
    .replace(/\b(19[89]\d|20[0-3]\d)\b/g, " ")                                              // years are fine
    // the customer's own loan amount ("your 50k ADCB loan", "outstanding AED 50,000") is not a price
    .replace(/\b(loan|outstanding|balance|settle\w*|bank|mortgage|finance|adcb|enbd|fab|mashreq|dib|adib|rakbank|cbd)\b[^.?!\n]{0,40}?(aed|dhs)?\s*\d[\d,.]*\s*(k|thousand|aed|dhs)?/gi, " ")
    .replace(/(aed|dhs)?\s*\d[\d,.]*\s*(k|thousand|aed|dhs)?\s+(loan|outstanding|left on the loan|remaining)\b/gi, " ");
  return /\b(aed|dhs?|dirhams?)\s*\.?\s*\d/i.test(t)
      || /\d[\d,.]*\s*(k|thousand|aed|dhs|dirhams?)\b/i.test(t)
      || /\b\d{1,3}(,\d{3})+\b/.test(t)
      || /\b\d{5,}\b/.test(t);
}

function sanitizeReply(text: string): string {
  // Never send the model's own self-corrections ("Wait, the rule says… Let me correct that: …")
  if (/\b(wait,? the rule|the rules? says?|let me correct|let me fix|i should (ask|say|not)|according to (my|the) (rules|instructions)|my instructions|per the rules|correction:)/i.test(text)) {
    const after = text.split(/let me (correct|fix) (that|this)[:.]?|correction:/i).pop() ?? "";
    const clean = after.replace(/^[\s:.-]+/, "").trim();
    console.warn("[Kaya] stripped self-correction from reply:", text.slice(0, 200));
    text = clean && !/\b(rule|instruction|i should)\b/i.test(clean) ? clean
      : text.split(/\n\s*\n/).filter(p => !/\b(wait|rule|instruction|let me|i should)\b/i.test(p)).pop() ?? "";
  }
  // Never "Wow" (Marc)
  text = text.replace(/\bwow+\b[!,.]*\s*/gi, "");
  // No filler openers like "Of course!" — just continue
  text = text.replace(/^\s*(of course|sure thing|absolutely|certainly)[!,.]?\s*/i, "");
  text = text.charAt(0).toUpperCase() + text.slice(1);
  // English only — strip Arabic greetings/words the model may mirror
  text = text
    .replace(/\b(wa\s*)?(alaikum|alaykum|aleikum)\s*(a?s+)?[\s-]*salaa?m\b[,!.]?\s*/gi, "Hi ")
    .replace(/\b(as+alaa?mu?\s*alaikum|salaa?m(\s+alaikum)?)\b[,!.]?\s*/gi, "Hi ")
    .replace(/[,\s]*\b(inshallah|insha'?\s*allah|mashallah|masha'?\s*allah|habibi|yalla|shukran|alhamdulillah)\b[,!.]?/gi, "")
    .replace(/\bHi\s+Hi\b/g, "Hi")
    .replace(/[\u0600-\u06FF]+/g, "")
    .replace(/[ \t]{2,}/g, " ").trim();
  // House style: no emojis after the first greeting
  if (!/I'm Kaya from Mister Wheelz/i.test(text)) {
    text = text.replace(/[\p{Extended_Pictographic}\u{1F3FB}-\u{1F3FF}\uFE0F\u200D]/gu, "").replace(/[ \t]{2,}/g, " ").replace(/\s+([.,!?])/g, "$1").trim();
  }
  if (/ABSOLUTE RULES|KNOWLEDGE BASE|What you already know|next_action|system prompt|my instructions|I was instructed|I('| a)m programmed/i.test(text)) {
    console.warn("[Kaya] blocked reply that leaked instructions:", text);
    return SAFE_LEAK_REPLY;
  }
  if (containsPrice(text)) {
    console.warn("[Kaya] blocked reply containing a price:", text);
    return SAFE_PRICE_REPLY;
  }
  return text;
}

// Everything before the per-customer part is identical for every chat → cache it
function splitSystem(full: string) {
  let cut = full.indexOf("\nWhat you already know:");
  if (cut < 0) cut = full.indexOf("\n\nCurrent step:");
  if (cut < 0) return [cached(full)];
  return [cached(full.slice(0, cut)), { type: "text" as const, text: full.slice(cut) }];
}

export let lastKayaUsage: unknown = null;

// ─── Kaya reply ───────────────────────────────────────────────────────────────

export async function getKayaReply(
  step: number,
  history: ConversationMessage[],
  customerMessage: string,
  known: KnownFields = {}
): Promise<string> {
  const messages: ConversationMessage[] = [
    ...history,
    { role: "user", content: customerMessage.trim() || "(no message)" },
  ];

  try {
    const response = await anthropic.messages.create({
      model: KAYA_MODEL,
      max_tokens: KAYA_MAX_TOKENS,
      system: splitSystem(buildSystemPrompt(step, known)),
      messages,
    });

    lastKayaUsage = response.usage;
    const u = response.usage as any;
    console.log(`[Kaya] tokens in=${u.input_tokens} cache_read=${u.cache_read_input_tokens ?? 0} cache_write=${u.cache_creation_input_tokens ?? 0} out=${u.output_tokens}`);
    const textBlock = response.content.find((block) => block.type === "text");
    if (textBlock?.type === "text") return sanitizeReply(textBlock.text.trim());

    // Extended thinking models (Sonnet 5) can emit only thinking blocks when max_tokens is tight.
    // If we land here, log what arrived so we can debug in Vercel logs.
    console.error("[Kaya] No text block. Content types:", response.content.map((b) => b.type).join(", "));
    return "Sorry, could you say that again?";
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : "Unknown error";
    console.error("[Kaya] Claude API error:", msg);
    return "Sorry, I'm having a little trouble right now — could you try again in a moment? 🙏";
  }
}

// ─── Appointment extractor ────────────────────────────────────────────────────

/**
 * Parses a free-text appointment message into a separate date and time string.
 * Returns empty strings if not found.
 */
export async function extractAppointment(
  text: string
): Promise<{ appointment_date: string; appointment_time: string }> {
  try {
    const response = await anthropic.messages.create({
      model: EXTRACTOR_MODEL,
      max_tokens: 120,
      ...NO_THINKING,
      system: `Extract an appointment date and time from a WhatsApp message.
Return ONLY a JSON object with keys "appointment_date" and "appointment_time".
- "appointment_date": day/date as written (e.g. "Monday", "Tomorrow", "July 10", "Sunday"). Use "" if not found.
- "appointment_time": time as written (e.g. "3pm", "11:00 AM", "morning", "afternoon"). Use "" if not found.
Examples:
"Tomorrow at 3pm"       → {"appointment_date":"Tomorrow","appointment_time":"3pm"}
"Monday morning"        → {"appointment_date":"Monday","appointment_time":"morning"}
"Sunday 2pm"            → {"appointment_date":"Sunday","appointment_time":"2pm"}
"Friday at 11am"        → {"appointment_date":"Friday","appointment_time":"11am"}
"anytime this week"     → {"appointment_date":"This week","appointment_time":""}
The message may also contain questions — never answer them, only extract the date/time the customer wants to come.`,
      messages: [{ role: "user", content: `Customer message:\n<<<${text}>>>\n\nReturn only the JSON object.` }],
    });
    const block = response.content.find((b) => b.type === "text");
    if (block?.type === "text") {
      const match = block.text.match(/\{[^}]*\}/);
      if (match) {
        const r = JSON.parse(match[0]);
        if (r.appointment_date || r.appointment_time) return r;
      }
    }
  } catch (e) {
    console.error("[extractAppointment] error:", e);
  }
  // Fallback: plain day + time in the text ("tomorrow evening at 6pm")
  const day = text.match(/\b(today|tonight|tomorrow|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/i)?.[1] ?? "";
  const times = [...text.matchAll(/\b(\d{1,2}(?::\d{2})?\s*(?:am|pm))\b/gi)].map(m => m[1]);
  // "10 AM won't work, can we do 6 PM instead" → the last time mentioned
  return { appointment_date: day, appointment_time: times.length ? times[times.length - 1] : "" };
}

// ─── Wants a real person? (backstop for wordings the patterns miss) ──────────
export async function wantsHuman(text: string): Promise<boolean> {
  try {
    const response = await anthropic.messages.create({
      model: EXTRACTOR_MODEL,
      max_tokens: 10,
      ...NO_THINKING,
      system: `You read one WhatsApp message a customer sent to Kaya, the AI assistant of a car-buying company.
Answer "YES" if the customer wants to talk to a real person / human / staff member instead of the bot, wants a call from the team, doesn't want to talk to a bot or AI, or asks whether they are talking to a bot in a way that shows they'd rather have a person.
Answer "NO" for everything else (questions about the car, price, location, booking, or the customer saying THEY will call or contact later).
Reply with only YES or NO.`,
      messages: [{ role: "user", content: `<<<${text}>>>` }],
    });
    const block = response.content.find((b) => b.type === "text");
    return block?.type === "text" && /^\s*yes/i.test(block.text);
  } catch (e) {
    console.error("[wantsHuman] error:", e);
    return false;
  }
}

// ─── Vehicle info extractor ───────────────────────────────────────────────────

/**
 * Scans ANY customer message for vehicle fields (make/model/year/mileage/specs).
 * Returns only fields it found with confidence — omits unknowns.
 * Safe to call on every message at every step.
 */
export async function extractVehicleInfo(
  messageText: string,
  alreadyKnown: VehicleFields = {}
): Promise<VehicleFields> {
  const knownSummary = Object.entries(alreadyKnown)
    .filter(([, v]) => v)
    .map(([k, v]) => `${k}: ${v}`)
    .join(", ");

  try {
    const response = await anthropic.messages.create({
      model: EXTRACTOR_MODEL,
      max_tokens: EXTRACTOR_MAX_TOKENS,
      ...NO_THINKING,
      system: [cached(`You extract structured car data from a customer WhatsApp message to store in a CRM. Accuracy is critical — wrong data is worse than no data. If you are not 100% sure, return "Unknown" or omit the field.

Return ONLY a JSON object with the fields you are certain about:
- "make"    — must exactly match one of the valid makes below. Use the canonical spelling. If unsure, omit.
- "model"   — must be a known model for that make (see reference). No make name, no year. If unsure, omit.
- "year"    — 4-digit year 1990–2026 as string. Only if explicitly stated.
- "mileage" — digits only (e.g. "125000"). "k"/"K" = ×1000. Only if clearly the odometer reading.
- "specs"   — exactly "GCC" or "Unknown". Only an explicit GCC market-spec statement proves GCC. Non-GCC is set by the webhook only after checking the Mulkiya engine-number field for NONE/NIL/blank. Named non-GCC markets (American, European, Japanese, Korean, Chinese) require that check. Any country name or purchase location, even "German specs", is Unknown; do not infer market specs from country of origin.

Valid makes: ${MAKES_LIST}

Model reference (make: models):
${Object.entries(CAR_MODELS).map(([m, ms]) => `${m}: ${ms.join(", ")}`).join("\n")}

Strict rules:
- If the make looks like a typo or phonetic variation of a known make (e.g. "Toyata" → "Toyota", "Mercedez" → "Mercedes-Benz"), set make to the canonical spelling and add a typo_check entry. Only use "Unknown" if you genuinely cannot determine which make was meant.
- If the model looks like a typo or phonetic variation of a known model for that make (e.g. "Landcrusier" → "Land Cruiser", "Corolle" → "Corolla"), set model to the canonical model name and add a typo_check entry.
- If the customer clearly names a model you don't recognise (many regional / GCC-only models exist, e.g. Ford Figo, Nissan Sunny, Toyota Rush, Chevrolet Groove), keep EXACTLY what they wrote as the model — never "Unknown" and never a guess.
- Never put model name in "make" or vice versa. Never put year in "model".
- Do NOT overwrite fields listed as already known in the message.
- If nothing vehicle-related is in the message, return {}.
- Messages may contain filler words ("sorry", "actually", "I mean", "oops", "it's the"). Extract the vehicle fields and ignore the filler.
- For each suspected typo add an entry to "typo_check": [{"field":"make"|"model"|"year", "input":"what they typed", "suggestion":"what you think they meant"}]

Examples:
"BMW X5 2019"             → {"make":"BMW","model":"X5","year":"2019"}
"toyota camry 2021"       → {"make":"Toyota","model":"Camry","year":"2021"}
"it's a Patrol"           → {"make":"Nissan","model":"Patrol"}
"125k km gcc"             → {"mileage":"125000","specs":"GCC"}
"Mercedes C200 2022 GCC"  → {"make":"Mercedes-Benz","model":"C-Class","year":"2022","specs":"GCC"}
"Ford Figo 2016"          → {"make":"Ford","model":"Figo","year":"2016"}
"Toyata Camry"            → {"make":"Toyota","model":"Camry","typo_check":[{"field":"make","input":"Toyata","suggestion":"Toyota"}]}
"Mercedez GLC"            → {"make":"Mercedes-Benz","model":"GLC","typo_check":[{"field":"make","input":"Mercedez","suggestion":"Mercedes-Benz"}]}
"Toyota Landcrusier 2020" → {"make":"Toyota","model":"Land Cruiser","year":"2020","typo_check":[{"field":"model","input":"Landcrusier","suggestion":"Land Cruiser"}]}
"x5" (BMW already known)  → {"model":"X5"}
"X7 sorry" (BMW known)    → {"model":"X7"}
"sorry it's the X7" (BMW) → {"model":"X7"}
"I mean the Camry" (Toyota) → {"model":"Camry"}
"camry" (Toyota known)    → {"model":"Camry"}
"patrol" (Nissan known)   → {"model":"Patrol"}
"I want to sell my car"   → {}
"just told you"           → {}
"yes" / "ok"              → {}`)],
      messages: [{ role: "user", content: `Already known: ${knownSummary || "nothing yet"}\n\nCustomer message: ${messageText}` }],
    });

    const block = response.content.find((b) => b.type === "text");
    if (block?.type === "text") {
      const match = block.text.match(/\{[\s\S]*\}/);
      if (!match) return {};
      const parsed = JSON.parse(match[0]);
      const result: VehicleFields = {};
      for (const key of ["make","model","year","mileage","specs"] as const) {
        if (typeof parsed[key] === "string" && parsed[key].trim()) result[key] = parsed[key].trim();
      }
      // Guard: if extracted mileage looks like a year (1990–2030), it's a year, not mileage
      if (result.mileage) {
        const km = parseInt(result.mileage, 10);
        if (km >= 1990 && km <= 2030) delete result.mileage;
      }
      if (Array.isArray(parsed.typo_check) && parsed.typo_check.length > 0) {
        result.typo_check = parsed.typo_check;
      }
      return result;
    }
  } catch (e) {
    console.error("[extractVehicleInfo] error:", e);
  }
  return {};
}

