              </button>
            )}
            {isSuper && <a href="/monitor/improve" style={{ ...S.iconBtn, width: 38, height: 38, padding: 0, borderRadius: 10, textDecoration: "none", color: "#fd9800", fontSize: 12, whiteSpace: "nowrap" }} title="Kaya Improve" aria-label="Open Kaya Improve"><KayaImproveIcon size={32}/></a>}
            {isSuper && <button style={{...S.iconBtn,width:38,height:38,borderRadius:10}} title="Settings" aria-label="Open settings" onClick={() => setSettings(true)}><SettingsIcon size={32}/></button>}
          </div>
        </div>

        <div style={S.searchWrap}>
