"use client";
import KayaImproveIcon from "@/components/KayaImproveIcon";

import { useEffect, useRef, useState, useCallback } from "react";
import { useRouter } from "next/navigation";

// ── Types ──────────────────────────────────────────────────────────────────────

interface Message { role: "user" | "assistant"; content: string; }

interface Conv {
  phone: string; step: number; name: string | null;
  make: string | null; model: string | null; year: string | null;
  mileage: string | null; specs: string | null; loan: string | null;
  sell_timeline: string | null; appointment: string | null;
  appointment_date: string | null; appointment_time: string | null;
  last_message_at: string | null; messages: Message[] | null;
}

interface LoginRecord { id: number; username: string; ip: string; user_agent: string; logged_in_at: string; }
interface UserRecord  { username: string; role: "super_admin" | "call_center"; password: string | null; email: string | null; created_at: string; }

// ── Helpers ────────────────────────────────────────────────────────────────────

function relativeTime(iso: string | null): string {
  if (!iso) return "";
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

function fmtDate(iso: string): string {
  return new Date(iso).toLocaleString("en-GB", {
    day: "2-digit", month: "short", year: "numeric",
    hour: "2-digit", minute: "2-digit",
  });
}

function stepLabel(step: number): string {
  return ["New","Name","Phone","Car info","Mileage/Specs","Loan","Timeline","Appointment","Complete ✓"][step] ?? `Step ${step}`;
}

function stepColor(step: number): string {
  if (step === 0) return "#8696a0";
  if (step <= 2) return "#f59e0b";
  if (step <= 5) return "#3b82f6";
  if (step === 7) return "#a855f7";
  if (step >= 8) return "#25d366";
  return "#8696a0";
}

function avatarInitial(conv: Conv): string {
  if (conv.name) return conv.name[0].toUpperCase();
  return conv.phone.replace(/\D/g, "").slice(-2);
}

function avatarColor(phone: string): string {
  const colors = ["#d97706","#059669","#7c3aed","#dc2626","#0284c7","#ea580c","#16a34a","#be185d","#0891b2","#65a30d"];
  let hash = 0;
  for (const ch of phone) hash = (hash * 31 + ch.charCodeAt(0)) & 0xffffffff;
  return colors[Math.abs(hash) % colors.length];
}

function lastPreview(conv: Conv): string {
  const msgs = conv.messages;
  if (!msgs || msgs.length === 0) return "No messages yet";
  const last = msgs[msgs.length - 1];
  return last.content.replace(/\n/g, " ").slice(0, 55) + (last.content.length > 55 ? "…" : "");
}

// ── Settings Panel ─────────────────────────────────────────────────────────────

function SettingsPanel({ onClose, me }: { onClose: () => void; me: string }) {
  const router = useRouter();
  const [tab, setTab] = useState<"history" | "users">("history");
  const [logins, setLogins] = useState<LoginRecord[]>([]);
  const [users, setUsers]   = useState<UserRecord[]>([]);
  const [newUser, setNewUser] = useState({ username: "", password: "", role: "call_center", email: "" });
  const [needsMigration, setNeedsMigration] = useState(false);
  const [menuFor, setMenuFor] = useState<string | null>(null);
  const menuItem: React.CSSProperties = { display: "block", width: "100%", textAlign: "left", background: "none", border: "none",
    color: "#e9edef", padding: "10px 14px", fontSize: 14, cursor: "pointer" };
  const [addError, setAddError] = useState("");
  const [addOk, setAddOk] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("/api/monitor/users")
      .then((r) => r.json())
      .then((d) => { setLogins(d.logins ?? []); setUsers(d.users ?? []); setNeedsMigration(!!d.needsMigration); setLoading(false); });
  }, []);

  async function reloadUsers() {
    const d = await fetch("/api/monitor/users").then((r) => r.json());
    setUsers(d.users ?? []);
  }

  async function changeRole(username: string, role: string) {
    const res = await fetch("/api/monitor/users", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username, role }) });
    if (!res.ok) alert((await res.json()).error ?? "Failed");
    reloadUsers();
  }

  async function changePassword(username: string) {
    const password = prompt(`New password for ${username}:`);
    if (!password?.trim()) return;
    const res = await fetch("/api/monitor/users", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username, password }) });
    if (!res.ok) alert((await res.json()).error ?? "Failed");
    reloadUsers();
  }

  async function changeEmail(username: string, current: string | null) {
    const email = prompt(`Email for ${username} (used for "Forgot password", super admins only). Leave empty to remove:`, current ?? "");
    if (email === null) return;
    const res = await fetch("/api/monitor/users", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username, email }) });
    if (!res.ok) alert((await res.json()).error ?? "Failed");
    reloadUsers();
  }

  async function deleteUser(username: string) {
    if (!confirm(`Delete user ${username}?`)) return;
    const res = await fetch("/api/monitor/users", { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username }) });
    if (!res.ok) alert((await res.json()).error ?? "Failed");
    reloadUsers();
  }

  async function handleAddUser(e: React.FormEvent) {
    e.preventDefault();
    setAddError(""); setAddOk(false);
    const res = await fetch("/api/monitor/users", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newUser),
    });
    if (res.ok) {
      setAddOk(true);
      setNewUser({ username: "", password: "", role: "call_center", email: "" });
      reloadUsers();
    } else {
      const d = await res.json();
      setAddError(d.error ?? "Failed to add user");
    }
  }

  async function handleLogout() {
    await fetch("/api/monitor/logout", { method: "POST" });
    router.push("/monitor/login");
  }

  // Parse browser from user agent
  function parseBrowser(ua: string): string {
    if (ua.includes("Chrome") && !ua.includes("Edg")) return "Chrome";
    if (ua.includes("Firefox")) return "Firefox";
    if (ua.includes("Safari") && !ua.includes("Chrome")) return "Safari";
    if (ua.includes("Edg")) return "Edge";
    return "Browser";
  }

  return (
    <div style={SP.overlay} onClick={onClose}>
      <div style={SP.panel} onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div style={SP.header}>
          <div>
            <div style={SP.title}>⚙ Settings</div>
            <div style={SP.sub}>WhatsApp AI Bot · Kaya</div>
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <button style={SP.logoutBtn} onClick={handleLogout}>Sign out</button>
            <button style={SP.closeBtn} onClick={onClose}>✕</button>
          </div>
        </div>

        {/* Tabs */}
        <div style={SP.tabs}>
          <button
            style={{ ...SP.tab, ...(tab === "history" ? SP.tabActive : SP.tabInactive) }}
            onClick={() => setTab("history")}
          >
            Login History
          </button>
          <button
            style={{ ...SP.tab, ...(tab === "users" ? SP.tabActive : SP.tabInactive) }}
            onClick={() => setTab("users")}
          >
            Users
          </button>
        </div>

        <div style={SP.body}>
          {loading && <div style={SP.dimText}>Loading…</div>}

          {/* Login History tab */}
          {!loading && tab === "history" && (
            <div>
              <div style={SP.sectionTitle}>Recent logins</div>
              {logins.length === 0 && <div style={SP.dimText}>No login history yet.</div>}
              <div style={SP.loginList}>
                {logins.map((l) => (
                  <div key={l.id} style={SP.loginRow}>
                    <div style={SP.loginAvatar}>{l.username[0].toUpperCase()}</div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={SP.loginName}>{l.username}
                        <span style={SP.loginBrowser}> · {parseBrowser(l.user_agent)}</span>
                      </div>
                      <div style={SP.loginMeta}>
                        <span style={SP.ipBadge}>🌐 {l.ip}</span>
                        <span style={SP.loginTime}>{fmtDate(l.logged_in_at)}</span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Users tab */}
          {!loading && tab === "users" && (
            <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>
              {/* Existing users */}
              {needsMigration && <div style={SP.errMsg}>Database update needed for emails (run the SQL).</div>}
              <div>
                <div style={SP.sectionTitle}>Active users</div>
                <div style={SP.userList}>
                  {users.map((u) => (
                    <div key={u.username} style={{ ...SP.userRow, alignItems: "flex-start" }}>
                      <div style={SP.loginAvatar}>{u.username[0].toUpperCase()}</div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={SP.loginName}>
                          {u.username}{" "}
                          <span style={{ fontSize: 11, fontWeight: 600, padding: "2px 8px", borderRadius: 10, marginLeft: 6,
                            background: u.role === "super_admin" ? "#3b2a05" : "#0b3a2e", color: u.role === "super_admin" ? "#f5c542" : "#25d366" }}>
                            {u.role === "super_admin" ? "Super admin" : "Call center"}
                          </span>
                        </div>
                        <div style={{ fontSize: 13, color: "#e9edef", margin: "4px 0", fontFamily: "monospace" }}>
                          🔑 {u.password ?? <span style={{ color: "#8696a0", fontFamily: "inherit" }}>shows after next login</span>}
                        </div>
                        {u.email && <div style={{ fontSize: 12, color: "#8696a0", marginBottom: 2 }}>✉ {u.email}</div>}
                        <div style={SP.loginTime}>Added {fmtDate(u.created_at)}</div>
                      </div>
                      {(
                        <div style={{ position: "relative" }}>
                          <button style={{ ...SP.closeBtn, padding: "4px 10px", fontSize: 18, lineHeight: 1 }}
                            onClick={() => setMenuFor(menuFor === u.username ? null : u.username)}>⋮</button>
                          {menuFor === u.username && (
                            <div style={{ position: "absolute", right: 0, top: 34, zIndex: 20, background: "#233138", border: "1px solid #2a3942",
                              borderRadius: 8, minWidth: 190, boxShadow: "0 6px 20px rgba(0,0,0,.4)", overflow: "hidden" }}>
                              {u.username !== me && (
                                <button style={menuItem} onClick={() => { setMenuFor(null); changeRole(u.username, u.role === "super_admin" ? "call_center" : "super_admin"); }}>
                                  Make {u.role === "super_admin" ? "call center" : "super admin"}
                                </button>
                              )}
                              <button style={menuItem} onClick={() => { setMenuFor(null); changePassword(u.username); }}>Change password</button>
                              <button style={menuItem} onClick={() => { setMenuFor(null); changeEmail(u.username, u.email); }}>{u.email ? "Change email" : "Add email"}</button>
                              {u.role !== "super_admin" && u.username !== me && (
                                <button style={{ ...menuItem, color: "#ff6b6b" }} onClick={() => { setMenuFor(null); deleteUser(u.username); }}>Delete user</button>
                              )}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              {/* Add new user */}
              <div>
                <div style={SP.sectionTitle}>Add new user</div>
                <form onSubmit={handleAddUser} style={SP.addForm}>
                  <input
                    style={SP.input}
                    placeholder="Username"
                    value={newUser.username}
                    onChange={(e) => setNewUser((p) => ({ ...p, username: e.target.value }))}
                    required
                  />
                  <input
                    style={SP.input}
                    type="text"
                    placeholder="Password"
                    value={newUser.password}
                    onChange={(e) => setNewUser((p) => ({ ...p, password: e.target.value }))}
                    required
                  />
                  <input
                    style={SP.input}
                    type="email"
                    placeholder="Email (optional, for password reset)"
                    value={newUser.email}
                    onChange={(e) => setNewUser((p) => ({ ...p, email: e.target.value }))}
                  />
                  <select
                    style={SP.input}
                    value={newUser.role}
                    onChange={(e) => setNewUser((p) => ({ ...p, role: e.target.value }))}
                  >
                    <option value="call_center">Call center</option>
                    <option value="super_admin">Super admin</option>
                  </select>
                  {addError && <div style={SP.errMsg}>{addError}</div>}
                  {addOk   && <div style={SP.okMsg}>User added ✓</div>}
                  <button style={SP.addBtn} type="submit">Add user</button>
                </form>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ── Main component ─────────────────────────────────────────────────────────────

export default function MonitorPage() {
  const [convs, setConvs]         = useState<Conv[]>([]);
  const [active, setActive]       = useState<string | null>(null);
  const [search, setSearch]       = useState("");
  const [filter, setFilter]       = useState<"all"|"active"|"complete">("all");
  const [loading, setLoading]     = useState(true);
  const [settings, setSettings]   = useState(false);
  const [resetting, setResetting] = useState(false);
  const [role, setRole]           = useState<string | null>(null);
  const [meName, setMeName]       = useState("");
  useEffect(() => { fetch("/api/monitor/me", { cache: "no-store" }).then((r) => r.ok ? r.json() : null).then((d) => { setRole(d?.role ?? null); setMeName(d?.username ?? ""); }).catch(() => {}); }, []);
  const isSuper = role === "super_admin";
  async function signOut() { await fetch("/api/monitor/logout", { method: "POST" }); window.location.href = "/monitor/login"; }
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const prevLenRef = useRef<Record<string, number>>({});

  const fetchConvs = useCallback(async () => {
    try {
      const res = await fetch("/api/conversations", { cache: "no-store" });
      if (!res.ok) return;
      setConvs(await res.json());
      setLoading(false);
    } catch { setLoading(false); }
  }, []);

  useEffect(() => { fetchConvs(); const id = setInterval(fetchConvs, 5000); return () => clearInterval(id); }, [fetchConvs]);

  useEffect(() => {
    const c = convs.find((c) => c.phone === active);
    if (!c) return;
    const newLen = c.messages?.length ?? 0;
    if (newLen > (prevLenRef.current[active!] ?? 0)) messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    prevLenRef.current[active!] = newLen;
  }, [convs, active]);

  const filtered = convs.filter((c) => {
    const s = c.phone.includes(search) || (c.name ?? "").toLowerCase().includes(search.toLowerCase());
    const f = filter === "all" || (filter === "complete" && c.step >= 8) || (filter === "active" && c.step < 8);
    return s && f;
  });

  const activeConv = convs.find((c) => c.phone === active) ?? null;

  // Collapsible sidebar (desktop) + one-panel view on phones, like WhatsApp
  const [collapsed, setCollapsed] = useState(false);
  const [isMobile, setIsMobile] = useState(false);
  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check(); window.addEventListener("resize", check);
    return () => window.removeEventListener("resize", check);
  }, []);
  const showSidebar = isMobile ? !activeConv : !collapsed;
  const showChat = isMobile ? !!activeConv : true;

  async function handleReset() {
    if (!active || resetting) return;
    if (!confirm("Reset this conversation? All data will be cleared.")) return;
    setResetting(true);
    await fetch("/api/reset-conversation", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ phone: active }) });
    await fetchConvs();
    setResetting(false);
  }

  return (
    <div style={S.app}>
      {settings && isSuper && <SettingsPanel me={meName} onClose={() => setSettings(false)} />}

      {/* ── SIDEBAR ── */}
      <div style={{ ...S.sidebar, ...(showSidebar ? {} : { display: "none" }), ...(isMobile ? { width: "100%", minWidth: 0 } : {}) }}>
        <div style={S.sideHeader}>
          <div style={S.botRow}>
            <img src="/mw-logo.png" alt="Mister Wheelz" style={S.botAvatar} />
            <div>
              <div style={S.botName}>WhatsApp AI Bot</div>
              <div style={S.botSub}><span style={S.dot} />Kaya · Mister Wheelz</div>
            </div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <div style={S.convCount}>{convs.length}</div>
            {!isSuper && role && (
              <button style={S.iconBtn} title="Sign out" onClick={signOut}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/></svg>
              </button>
            )}
            {isSuper && <a href="/monitor/improve" style={{ ...S.iconBtn, width: "auto", height: 38, padding: "0 10px", gap: 7, borderRadius: 10, textDecoration: "none", color: "#fd9800", fontSize: 12, whiteSpace: "nowrap" }} title="Kaya Improve" aria-label="Open Kaya Improve"><KayaImproveIcon size={28}/>Improve</a>}
            {isSuper && <button style={S.iconBtn} title="Settings" onClick={() => setSettings(true)}>
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="12" cy="12" r="3"/>
