import Anthropic from "@anthropic-ai/sdk";
import { MAKES_LIST, CAR_MODELS } from "./carData";

const anthropic = new Anthropic({
  apiKey: process.env.ANTHROPIC_API_KEY as string,
});

const KAYA_MODEL      = "claude-haiku-5-5"; // chat replies (adaptive thinking on)
const EXTRACTOR_MODEL = "claude-haiku-5-5"; // car extraction, appointment parsing, CRM summary (thinking off)
const KAYA_MAX_TOKENS      = 2048; // thinking tokens count toward this — keep headroom so text always follows
const EXTRACTOR_MAX_TOKENS =  200;
// Background tasks are simple JSON/notes — no thinking, so small max_tokens can't end before the text
const NO_THINKING = { thinking: { type: "disabled" as const } };
// Static system text is cached (Haiku 5.5 caches from 512 tokens) — repeat reads cost ~10%
const cached = (text: string) => ({ type: "text" as const, text, cache_control: { type: "ephemeral" as const } });
/** @deprecated use KAYA_MAX_TOKENS / EXTRACTOR_MAX_TOKENS */
const MAX_TOKENS = KAYA_MAX_TOKENS;

// ─── Types ────────────────────────────────────────────────────────────────────

export type ConversationMessage = {
  role: "user" | "assistant";
  content: string;
};

export type KnownFields = {
  image_shared?: boolean | null;
  name?: string | null;
  phone_number?: string | null;
  car?: string | null;
  make?: string | null;
  model?: string | null;
  year?: string | null;
  mileage?: string | null;
  specs?: string | null;
  loan?: string | null;
  mortgage_amount?: string | null;
  sell_timeline?: string | null;
  sell_urgent?: boolean | null;
  dubai_hour?: number | null;
  dubai_datetime?: string | null;
  dubai_tomorrow?: string | null;
  booking_slot?: string | null;
  appointment?: string | null;
  appointment_date?: string | null;
  appointment_time?: string | null;
  typo_check?: TypoCheck[] | null;
  skip_mortgage?: boolean | null;
  next_action?: string | null;
  estimated_value?: string | null;
  owner_status?: string | null;       // "owner" | "poa" | unknown
  car_conditions?: string | null;     // free-text: accident history, mods, fines, etc.
  [key: string]: unknown;
};

export type TypoCheck = { field: string; input: string; suggestion: string };

export type VehicleFields = {
  make?: string;
  model?: string;
  year?: string;
  mileage?: string;
  specs?: string;
  typo_check?: TypoCheck[];
};

// ─── Step instructions ────────────────────────────────────────────────────────

const STEP_INSTRUCTIONS: Record<number, string> = {
  // ── STEP 0 — Greeting + name ─────────────────────────────────────────────
  0: `Check "What you already know" first.

Case A — car details are present (make/model/year etc. in context):
  Do NOT send the standard greeting. Instead write a SHORT message (2–3 sentences) that:
  1. Introduces yourself: "Good morning! I'm Kaya from Mister Wheelz 😊" (Good morning/afternoon/evening by Dubai time — never "Hi" or "Hello")
  2. Acknowledges what they shared: "I can see you have a [make] [model] [year]" — include only the fields you know.
  3. If this is the very first reply and the name is unknown, ask "Before we start may I know your name please?" (only once in the whole chat). If the name IS known: ask only the next missing item in this order — mileage & GCC/non-GCC specs → outstanding loan → when they plan to sell. Never ask cash or consignment here.

Case B — no car info yet (standard greeting):
  Send this EXACTLY:
  "Good morning! I'm Kaya from Mister Wheelz 😊 Before we start may I know your name please?"`,

  // ── STEP 1 — What car? → push for appointment as soon as make+model+year known ──
  1: `Goal: get the customer's name and find out what car they want to sell. Follow the order: name → car → mileage & specs → loan → when to sell → booking. Never jump ahead to booking here.

Check "What you already know" first.

If the customer gave their name in this message:
  - Reply: "Good morning/Good afternoon/Good evening [first name]! What car would you like to sell?" (by Dubai time: morning before 12:00, afternoon 12:00–17:00, evening after 17:00)
  - Do NOT wait for another message before asking the car.

If the message is only a greeting / filler with no name and no car info:
  - Reply exactly: "What car would you like to sell?" (no "Of course", no filler)

If the message contains car information:
  - Extract what you can. Check "What you already know".
  - If make + model + year are ALL known: acknowledge the car in a few words, then:
    - ask: "Mileage, and GCC specs?" (skip whatever they already gave). Never ask for their name here — if they didn't give it, it's asked after the booking.
    Do NOT ask for a visit time yet.
  - If make or model or year is STILL missing: ask ONLY for the FIRST missing field (make → model → year). One question only.

If the customer asks about price / how much we pay BEFORE we know the car (or refuses to give their name):
  - Do NOT mention price, offer or value at all. Just show understanding and move to the car.
  - Example: "No problem at all, happy to help. What car would you like to sell?"
