          }
        }
        // "weekend" → Saturday (closed on Sunday); also when "Weekend" was saved earlier as the day
        const nextSaturday = () => {
          const n = new Date(Date.now() + 4 * 3600e3);
          let add = (6 - n.getUTCDay() + 7) % 7;
          if (add === 0 && n.getUTCHours() >= 18) add = 7;
