-- Reuse the already-provisioned server-header policy, without changing or exposing its secret.
do $$ declare access_expression text; table_name text; begin
 select pg_get_expr(polqual,polrelid) into access_expression from pg_policy where polrelid='public.mw_improve_settings'::regclass and polname='server_only';
 if access_expression is null then raise exception 'Existing server policy required'; end if;
 foreach table_name in array array['mw_improve_proposals','mw_improve_releases','mw_improve_leases'] loop
  execute format('create policy server_only on public.%I for all to anon using (%s) with check (%s)',table_name,access_expression,access_expression);
  execute format('grant select,insert,update,delete on public.%I to anon',table_name);
 end loop;
end $$;
create index mw_improve_proposals_status on public.mw_improve_proposals(status,created_at);
create index mw_improve_releases_status on public.mw_improve_releases(status,created_at);
create function public.kaya_improve_lease(lease_name text, holder uuid, release_lease boolean default false)
returns boolean language plpgsql security invoker set search_path=public as $$
declare claimed uuid;
begin
 if release_lease then delete from public.mw_improve_leases where id=lease_name and token=holder; return found; end if;
 insert into public.mw_improve_leases(id,token,expires_at) values(lease_name,holder,now()+interval '15 minutes')
 on conflict(id) do update set token=excluded.token,expires_at=excluded.expires_at where mw_improve_leases.expires_at<now()
 returning token into claimed;
 return claimed=holder;
end $$;
revoke all on function public.kaya_improve_lease(text,uuid,boolean) from public;
grant execute on function public.kaya_improve_lease(text,uuid,boolean) to anon;
create table public.mw_improve_connection(id boolean primary key default true check(id),hook_id bigint not null,checked_at timestamptz not null default now());
alter table public.mw_improve_connection enable row level security;
do $$ declare e text; begin
 select pg_get_expr(polqual,polrelid) into e from pg_policy where polrelid='public.mw_improve_settings'::regclass and polname='server_only';
 execute format('create policy server_only on public.mw_improve_connection for all to anon using (%s) with check (%s)',e,e);
end $$;
grant select,insert,update,delete on public.mw_improve_connection to anon;

-- Apply only after all server clients include x-kaya-improve-secret.
-- Prevent public-key access to customer records, credentials and roles.
do $$ declare e text; t text; begin
 select pg_get_expr(polqual,polrelid) into e from pg_policy where polrelid='public.mw_improve_settings'::regclass and polname='server_only';
 if e is null then raise exception 'Server access policy required'; end if;
 foreach t in array array['mw_whatsapp','mw_monitor_users','mw_monitor_logins'] loop
  execute format('create policy kaya_server_only on public.%I for all to anon using (%s) with check (%s)',t,e,e);
  execute format('alter table public.%I enable row level security',t);
 end loop;
end $$;

import { createHash, randomUUID } from "crypto";
import catalog from "./learning.json";
import { Chat, detect } from "./detect";
import { independentlyValidate, propose, safeEvidence } from "./reviewer";
import { validateLearning, validateCandidate } from "./learning";
import { improveDb, settings } from "./store";
import { hash, publishReady, successfulMessages } from "./publisher";
import { AUTO_POLICY } from "./auto-policy";
export async function autoReview(chat:Chat){
 const state=await settings();if(!state.config.enabled||!state.config.autoApprove)return;
 const db=improveDb(),evidence=safeEvidence(chat),fingerprint=hash(JSON.stringify(evidence)),runId=`auto-review:${chat.phone}:${fingerprint}`;
 // Correct recorded bookings get lightweight checks; deeper review targets problems/non-bookings.
 const detected=detect(chat),needsReview=detected.findings.length>0||(!chat.appointment_date&&detected.outcome!=="not_ready");
 if(!needsReview){await publishReady();return;}
 const claimed=await db.from("mw_improve_runs").insert({id:runId,kind:"auto_approval",status:"running"});
 if(claimed.error?.code==="23505"){
  const old=await db.from("mw_improve_runs").select("status,started_at,finished_at").eq("id",runId).single();if(old.error)throw old.error;
  const retryable=["failed","skipped"].includes(old.data.status)&&Date.now()-Date.parse(old.data.finished_at??old.data.started_at)>60000;
  const expired=old.data.status==="running"&&Date.now()-Date.parse(old.data.started_at)>15*60000;
  if(!retryable&&!expired){await publishReady();return;}
  const retried=await db.from("mw_improve_runs").update({status:"running",started_at:new Date().toISOString(),finished_at:null,error:null}).eq("id",runId).eq("status",old.data.status).select("id");if(retried.error)throw retried.error;if(!retried.data?.length)return;
 }else if(claimed.error)throw claimed.error;
 const holder=randomUUID();const lease=await db.rpc("kaya_improve_lease",{lease_name:`review:${chat.phone}`,holder,release_lease:false});if(lease.error){await db.from("mw_improve_runs").update({status:"failed",finished_at:new Date().toISOString(),error:lease.error.message}).eq("id",runId);throw lease.error;}
 if(!lease.data){await db.from("mw_improve_runs").update({status:"skipped",finished_at:new Date().toISOString(),summary:{reason:"A review for this conversation is already running"}}).eq("id",runId);return;}
 try{
  const suggestions=await propose(chat),successful=await successfulMessages(),before=validateLearning(catalog);let approved=0,pending=0,rejected=0;
  for(const s of suggestions){
   const id=createHash("sha256").update(s.manual?`${fingerprint}:${s.reason}`:`${s.intent}:${s.phrase}`).digest("hex");
   const exists=await db.from("mw_improve_proposals").select("id").eq("id",id).maybeSingle();if(exists.error)throw exists.error;if(exists.data)continue;
   if(s.manual){const r=await db.from("mw_improve_proposals").insert({id,status:"needs_admin",severity:s.severity,reason:s.reason,evidence:{conversation:evidence,policy:AUTO_POLICY.version}});if(r.error)throw r.error;pending++;continue;}
   const alias={phrase:s.phrase!,intent:s.intent!};let validation:Record<string,unknown>,status:string;
   try{
    const independent=await independentlyValidate(alias,chat);if(!independent.passed)throw Error(`Independent review rejected: ${independent.reason}`);
    const tests=validateCandidate(before,validateLearning({version:1,aliases:[...before.aliases,alias]}),successful);
    validation={...tests,independent,policy:AUTO_POLICY.version,base_hash:hash(JSON.stringify(before)),evidence_hash:fingerprint};status="approved";approved++;
   }catch(e){validation={passed:false,reason:e instanceof Error?e.message:String(e),policy:AUTO_POLICY.version};status="rejected";rejected++;}
   const position=(chat.messages??[]).findIndex(m=>m.role==="user"&&m.content.toLowerCase().trim().replace(/[.!?,]+$/g,"").replace(/\s+/g," ")===alias.phrase);
   const response=position>=0?(chat.messages??[]).slice(position+1).find(m=>m.role==="assistant")?.content??"":"";
   const severity=alias.intent==="customer_will_call"&&/\b(?:our team|we|someone)\b.{0,40}\b(?:will call|will contact|will be in touch)/i.test(response)?"critical":"minor";
   const r=await db.from("mw_improve_proposals").insert({id,status,severity,...alias,reason:s.reason,evidence:{conversation:evidence,policy:AUTO_POLICY.version},validation});if(r.error&&r.error.code!=="23505")throw r.error;
  }
  // Deterministic serious findings outside the allowed patch scope always remain visible.
  for(const f of detected.findings.filter(f=>f.severity==="critical")){
   const id=hash(`${fingerprint}:${f.code}`);const r=await db.from("mw_improve_proposals").upsert({id,status:"needs_admin",severity:"critical",reason:f.message,evidence:{code:f.code,conversation:evidence,suggestion:f.suggestion,policy:AUTO_POLICY.version}},{onConflict:"id",ignoreDuplicates:true});if(r.error)throw r.error;
  }
  const done=await db.from("mw_improve_runs").update({status:"completed",finished_at:new Date().toISOString(),summary:{approved,needs_admin:pending,rejected,policy:AUTO_POLICY.version}}).eq("id",runId);if(done.error)throw done.error;
 }catch(e){await db.from("mw_improve_runs").update({status:"failed",finished_at:new Date().toISOString(),error:e instanceof Error?e.message:String(e)}).eq("id",runId);throw e;
 }finally{await db.rpc("kaya_improve_lease",{lease_name:`review:${chat.phone}`,holder,release_lease:true});}
 await publishReady();
}

export const AUTO_POLICY={version:"2026-10-15-v1",allowedPath:"lib/kaya-improve/learning.json",dailyMinorHours:24,maxBatch:5,
 locked:["Pricing and sales promises","Booking consent, availability and fallback times","Specs and Mulkiya decisions","Cancellation and rescheduling actions","Bigin record/task creation and duplication","Stop requests and callback consent","Business location, hours, services and contact number","Authentication, permissions, backups and approval rules"],
 scope:"Add exact English contact-language aliases only. No arbitrary code, prompt instructions, new names, booking actions or business-policy edits."} as const;
export function releaseDue(severity:"critical"|"minor",lastMinor:string|null,now=Date.now()) {return severity==="critical"||!lastMinor||now-Date.parse(lastMinor)>=24*3600e3;}
export function checkPublishGate(input:{enabled:boolean;hasBackup:boolean;validated:boolean;ci:boolean;preview:boolean;baseMatches:boolean;files:string[]}) {
 if(!input.enabled||!input.hasBackup||!input.validated||!input.ci||!input.preview||!input.baseMatches)throw Error("Release gate has not passed");
 if(input.files.length!==2||![AUTO_POLICY.allowedPath,"lib/kaya-improve/history.json"].every(p=>input.files.includes(p)))throw Error("Release touches a locked file");
 return true;
}

