export async function afterBiginPush(chat:Chat) {
 if(process.env.VERCEL_ENV && process.env.VERCEL_ENV!=="production")return;
 const state=await settings();if(!state.config.enabled)return;
 const db=improveDb();
 for(const run of RUNS) {
